head.script:
// 테스트 설명, 유효성 값 설정 (_2: set* 메서드의 인자로 separator 구분자가 사용되는지 검증)
scwin.tData = {
    "description" : "[multiselect > P > separator]<br/>Multiselect 컴포넌트에서 두 개 이상의 아이템을 선택했을때 Value 값을 구분하는 구분자를 설정합니다.",
    "validation" : [
        "setValue(), setSelectedIndex(), setText() 메소드로 아이템을 선택할 때 separator 구분자가 사용됩니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, separator 속성 적용)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cSeparator = con_separator.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="target1 : separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + ']"', '', 'label1');
    $c.gcm.createBasicMultiSelect(cList);
};



// setValue - separator 구분자로 구분된 Value 문자열로 다중 선택
scwin.btn_setValue_onclick = function (e) {
    let cSeparator = con_separator.getText() || " ";
    let inputVal = "1" + cSeparator + "3";
    target1.setValue(inputVal);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setValue('" + inputVal + "') 호출 후 getValue() : [" + target1.getValue() + "]");
};



// setText - separator 구분자로 구분된 Label 문자열로 다중 선택 (setText 는 label 값을 인자로 받음)
scwin.btn_setText_onclick = function (e) {
    let cSeparator = con_separator.getText() || " ";
    let inputVal = "multiselect1" + cSeparator + "multiselect3";
    target1.setText(inputVal);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setText('" + inputVal + "') 호출 후 getValue() : [" + target1.getValue() + "]");
};



// setSelectedIndex - separator 구분자로 구분된 인덱스 문자열로 다중 선택
scwin.btn_setSelectedIndex_onclick = function (e) {
    let cSeparator = con_separator.getText() || " ";
    let inputVal = "0" + cSeparator + "1" + cSeparator + "2";
    target1.setSelectedIndex(inputVal);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('" + inputVal + "') 호출 후 getValue() : [" + target1.getValue() + "]");
};
